using DentalLabOS.Application.Abstractions;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Hosting;
using QRCoder;

namespace DentalLabOS.Infrastructure.Services;

/// <summary>
/// Files on local disk under <c>Storage:RootPath</c> (default: App_Data/files under the content root, outside wwwroot).
/// Works on shared hosting and on a local server alike (plan 6.6). Keys are generated by the application.
/// </summary>
public sealed class LocalFileStorage(IConfiguration configuration, IHostEnvironment environment) : IFileStorage
{
    private readonly string _root = Path.GetFullPath(configuration["Storage:RootPath"] is { Length: > 0 } configured
        ? configured
        : Path.Combine(environment.ContentRootPath, "App_Data", "files"));

    public async Task SaveAsync(string key, Stream content, CancellationToken cancellationToken = default)
    {
        var path = PathOf(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        await using var file = new FileStream(path, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, useAsync: true);
        await content.CopyToAsync(file, cancellationToken);
    }

    public Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken = default) =>
        Task.FromResult<Stream>(new FileStream(PathOf(key), FileMode.Open, FileAccess.Read, FileShare.Read, 81920, useAsync: true));

    public Task DeleteAsync(string key, CancellationToken cancellationToken = default)
    {
        var path = PathOf(key);
        if (File.Exists(path))
        {
            File.Delete(path);
        }

        return Task.CompletedTask;
    }

    /// <summary>Rejects any key that would escape the storage root.</summary>
    private string PathOf(string key)
    {
        var full = Path.GetFullPath(Path.Combine(_root, key));
        if (!full.StartsWith(_root + Path.DirectorySeparatorChar, StringComparison.Ordinal))
        {
            throw new InvalidOperationException("Invalid storage key.");
        }

        return full;
    }
}

public sealed class QrCodeRenderer : IQrCodeRenderer
{
    public string Svg(string text)
    {
        using var generator = new QRCodeGenerator();
        using var data = generator.CreateQrCode(text, QRCodeGenerator.ECCLevel.M);
        return new SvgQRCode(data).GetGraphic(4);
    }
}

/// <summary>AUTH-08 branch choice: the X-Branch-Id header (API) or the dlos-branch cookie (web).</summary>
public sealed class HttpBranchSelection(IHttpContextAccessor accessor) : IBranchSelection
{
    public const string Cookie = "dlos-branch";
    public const string Header = "X-Branch-Id";

    public Guid? RequestedBranchId
    {
        get
        {
            var request = accessor.HttpContext?.Request;
            var raw = request?.Headers[Header].FirstOrDefault() ?? request?.Cookies[Cookie];
            return Guid.TryParse(raw, out var id) ? id : null;
        }
    }
}
